import type { createAdmin, createStorefront, initialize } from "arky-sdk";
import type {
  Collection,
  CollectionType,
  CreateEntryParams,
  CreateMediaParams,
  CreatePrivateCollectionParams,
  CreatePrivateEntryParams,
  Entry,
  EntryAccess,
  EntryAccessAction,
  EntryAccessActor,
  EntryOwner,
  EntryType,
  EpochMilliseconds,
  FindEntryAccessesParams,
  FindPrivateEntriesParams,
  FindSharedEntriesParams,
  Media,
  MediaFile,
  MediaImage,
  MediaVisibility,
  NoteEntryType,
  PaginatedResponse,
  PrivateCollection,
  PrivateEntry,
  PrivateEntryEditableStatus,
  PrivateEntryFileLinkParams,
  PrivateEntryType,
  PrivateFileLink,
  PublicCollection,
  PublicEntry,
  SharedEntry,
  SharedEntryFileLinkParams,
  StorePermission,
  StorePermissionAccess,
  UpdatePrivateCollectionParams,
  UpdatePrivateEntryParams,
} from "arky-sdk";

type Assert<T extends true> = T;
type Equal<A, B> = (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2 ? true : false;
type Missing<T, K extends PropertyKey> = K extends keyof T ? false : true;
type RequiredField<T, K extends keyof T> = {} extends Pick<T, K> ? false : true;
type Answer<F extends (...args: never[]) => unknown> = Awaited<ReturnType<F>>;
type Admin = ReturnType<typeof createAdmin>;
type Storefront = ReturnType<typeof createStorefront>;
type Store = ReturnType<typeof initialize>;

export type PrivateContentContracts = [
  Assert<Equal<Collection["type"], CollectionType>>,
  Assert<Equal<CollectionType, "public" | "private" | "shared" | "notes">>,
  Assert<Equal<Entry["type"], EntryType>>,
  Assert<Equal<EntryType["type"], "public" | "private_store" | "private_customer" | "private_company" | "private_order" | "private_conversation" | "private_form_submission" | "shared" | "note_customer" | "note_company" | "note_order" | "note_conversation" | "note_form_submission" | "note_form_submission_stage_change">>,
  Assert<Equal<Extract<EntryType, { type: "public" }>, { type: "public"; key: string; slugs: Record<string, string> }>>,
  Assert<Equal<Extract<EntryType, { type: "private_customer" }>, { type: "private_customer"; customer_id: string }>>,
  Assert<Equal<Extract<NoteEntryType, { type: "note_form_submission_stage_change" }>["changed_at"], EpochMilliseconds>>,
  Assert<Missing<Entry, "key" | "slugs" | "actor" | "owner">>,
  Assert<Equal<EntryOwner["type"], "store" | "customer" | "company" | "order" | "conversation" | "form_submission">>,
  Assert<Equal<CreatePrivateEntryParams["type"], PrivateEntryType | { type: "shared"; customer_id: string }>>,
  Assert<Missing<CreatePrivateEntryParams, "key" | "slugs" | "actor" | "owner">>,
  Assert<Missing<UpdatePrivateEntryParams, "type" | "key" | "slugs" | "owner">>,
  Assert<Missing<UpdatePrivateCollectionParams, "type">>,
  Assert<Equal<CreatePrivateCollectionParams["type"], "private" | "shared">>,
  Assert<RequiredField<CreatePrivateCollectionParams, "id">>,
  Assert<RequiredField<CreatePrivateEntryParams, "id">>,
  Assert<RequiredField<CreatePrivateEntryParams, "type">>,
  Assert<RequiredField<UpdatePrivateEntryParams, "expected_updated_at">>,
  Assert<Equal<PrivateEntryEditableStatus, { type: "active" } | { type: "draft" } | { type: "archived" }>>,
  Assert<Missing<CreateEntryParams, "type">>,
  Assert<Equal<FindPrivateEntriesParams["owner"], EntryOwner | undefined>>,
  Assert<Equal<keyof FindPrivateEntriesParams, "store_id" | "collection_id" | "owner" | "limit" | "cursor">>,
  Assert<Equal<keyof FindSharedEntriesParams, "collection_id" | "limit" | "cursor">>,
  Assert<Equal<keyof EntryAccess, "id" | "store_id" | "collection_id" | "entry_id" | "actor" | "action" | "at">>,
  Assert<Equal<EntryAccess["actor"], EntryAccessActor>>,
  Assert<Equal<EntryAccessActor["type"], "account_session" | "account_token" | "customer" | "arky">>,
  Assert<Equal<Extract<EntryAccessActor, { type: "account_token" }>, { type: "account_token"; account_id: string; email: string; account_token_id: string }>>,
  Assert<Equal<EntryAccessAction, "read" | "create" | "update" | "delete">>,
  Assert<Equal<EntryAccess["at"], EpochMilliseconds>>,
  Assert<Equal<PrivateFileLink, { url: string; expires_at: EpochMilliseconds }>>,
  Assert<Equal<StorePermissionAccess, "read" | "write">>,
  Assert<Equal<Extract<StorePermission, { type: "public_collections" }>, { type: "public_collections"; access: StorePermissionAccess }>>,
  Assert<Equal<Extract<StorePermission, { type: "collection" }>, { type: "collection"; collection_id: string; access: StorePermissionAccess }>>,
  Assert<Equal<Extract<StorePermission, { type: "content" | "private_content" }>, never>>,
  Assert<Equal<MediaVisibility, "public" | "private">>,
  Assert<Equal<Media["visibility"], MediaVisibility>>,
  Assert<Equal<CreateMediaParams["visibility"], MediaVisibility | undefined>>,
  Assert<Equal<MediaFile["url"], string | null>>,
  Assert<Equal<MediaImage["url"], string | null>>,
  Assert<Equal<Answer<Admin["content"]["collection"]["get"]>, PublicCollection>>,
  Assert<Equal<Answer<Admin["content"]["entry"]["get"]>, PublicEntry>>,
  Assert<Equal<Answer<Admin["content"]["privateCollection"]["find"]>, PaginatedResponse<PrivateCollection>>>,
  Assert<Equal<Answer<Admin["content"]["privateEntry"]["find"]>, PaginatedResponse<PrivateEntry>>>,
  Assert<Equal<Answer<Admin["content"]["privateEntry"]["fileLink"]>, PrivateFileLink>>,
  Assert<Equal<Parameters<Admin["content"]["privateEntry"]["fileLink"]>[0], PrivateEntryFileLinkParams>>,
  Assert<Equal<keyof Admin["content"]["entryAccess"], "find">>,
  Assert<Equal<Parameters<Admin["content"]["entryAccess"]["find"]>[0], FindEntryAccessesParams>>,
  Assert<Equal<Answer<Admin["content"]["entryAccess"]["find"]>, PaginatedResponse<EntryAccess>>>,
  Assert<Equal<{ store_id: string } extends FindEntryAccessesParams ? true : false, false>>,
  Assert<Equal<{ store_id: string; entry_id: string; account_id: string } extends FindEntryAccessesParams ? true : false, false>>,
  Assert<Equal<{ store_id: string; entry_id: string } extends FindEntryAccessesParams ? true : false, true>>,
  Assert<Equal<keyof Storefront["sharedEntries"], "find" | "get" | "fileLink">>,
  Assert<Equal<Answer<Storefront["sharedEntries"]["find"]>, PaginatedResponse<SharedEntry>>>,
  Assert<Equal<Answer<Storefront["sharedEntries"]["get"]>, SharedEntry>>,
  Assert<Equal<Parameters<Storefront["sharedEntries"]["fileLink"]>[0], SharedEntryFileLinkParams>>,
  Assert<Equal<Answer<Storefront["sharedEntries"]["fileLink"]>, PrivateFileLink>>,
  Assert<Equal<Store["sharedEntries"], Storefront["sharedEntries"]>>,
];
